1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
5	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
6	import org.springframework.stereotype.Component;
7	
8	/**
9	 * Derives the owner-identity values matching keys off: the owner's {@code customerCode} and the single
10	 * {@code identityKey} that all duplicate detection is expressed through. The identity key is the SHA-256 of the
11	 * owner's normalized telephone, email and last-name Soundex (see {@link SoundexResolver}). Keeping this
12	 * here (rather than in {@link OwnerMapper} or the REST controller) mirrors {@link HouseholdResolver},
13	 * {@link LocalityResolver} and {@link MembershipLevelResolver} and gives owner-identity derivation a single home.
14	 * Unlike the static utilities it collaborates with the field normalizers, so it is a Spring component.
15	 */
16	@Component
17	public class IdentityKeyResolver {
18	
19	    private final TelephoneNormalizer telephoneNormalizer;
20	
21	    private final EmailNormalizer emailNormalizer;
22	
23	    public IdentityKeyResolver(TelephoneNormalizer telephoneNormalizer,
24	                               EmailNormalizer emailNormalizer) {
25	        this.telephoneNormalizer = telephoneNormalizer;
26	        this.emailNormalizer = emailNormalizer;
27	    }
28	
29	    /**
30	     * Derives the owner's {@code identityKey}, the single value all duplicate detection is expressed through. It is the
31	     * full lower-case SHA-256 hex digest (64 characters) of {@code <normalizedTelephone>|<lowerEmail>|<soundex(lastName)>},
32	     * joining the canonical E.164 telephone (see {@link TelephoneNormalizer#canonicalize}), the normalized email (see
33	     * {@link EmailNormalizer#normalize}, empty when the owner has none) and the American Soundex of the owner's last
34	     * name (see {@link SoundexResolver#soundex}). Because the telephone is part of the key, two owners that differ only
35	     * in telephone — such as two members of the same household — have different keys; only owners whose whole key
36	     * matches are duplicates.
37	     *
38	     * @param owner the owner whose identity key should be derived
39	     * @return the owner's identity key
40	     */
41	    public String deriveIdentityKey(Owner owner) {
42	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
43	        String email = emailNormalizer.normalize(owner.getEmail());
44	        String lowerEmail = (email == null || email.isBlank()) ? "" : email.toLowerCase();
45	        String lastNameSoundex = SoundexResolver.soundex(owner.getLastName());
46	        return HexDigest.lowerHex(telephone + "|" + lowerEmail + "|" + lastNameSoundex);
47	    }
48	
49	    /**
50	     * Derives an owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}. {@code REGION} is the region code
51	     * derived from the owner's postcode (see {@link Region#forPostcode}), falling back to {@link LocalityResolver#UNKNOWN}
52	     * when the postcode maps to no known region; {@code HASH8} is the first 8 upper-case hex characters of the SHA-256
53	     * digest of the normalized telephone (see {@link TelephoneNormalizer#canonicalize}) concatenated with the owner's
54	     * last name (e.g. {@code NSW-1A2B3C4D}). Being a pure function of the postcode, telephone and last name it carries
55	     * no sequence number and is stable for a given owner.
56	     *
57	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
58	     * @return the generated customer code
59	     */
60	    public String deriveCustomerCode(Owner owner) {
61	        return regionCode(owner) + "-" + hash8(owner);
62	    }
63	
64	    /**
65	     * Returns the {@code REGION} segment of the owner's identifier: the region code derived from the owner's postcode
66	     * (see {@link Region#forPostcode}), falling back to {@link LocalityResolver#UNKNOWN} when the postcode maps to no
67	     * known region. Factored out of {@link #deriveCustomerCode} so the region segment has a single home, shared by every
68	     * identifier the owner's region prefixes.
69	     *
70	     * @param owner the owner whose region segment should be derived
71	     * @return the region code, or {@link LocalityResolver#UNKNOWN} when the postcode maps to no known region
72	     */
73	    private String regionCode(Owner owner) {
74	        Region region = Region.forPostcode(owner.getPostcode());
75	        return region == null ? LocalityResolver.UNKNOWN : region.name();
76	    }
77	
78	    /**
79	     * Returns the {@code HASH8} segment of the owner's identifier: the first 8 upper-case hex characters of the SHA-256
80	     * digest (see {@link HexDigest#upperHexPrefix}) of the owner's canonical telephone (see
81	     * {@link TelephoneNormalizer#canonicalize}) concatenated with the owner's last name. Factored out of
82	     * {@link #deriveCustomerCode} so the hash segment has a single home, shared by every identifier the owner's hash
83	     * contributes to.
84	     *
85	     * @param owner the owner whose hash segment should be derived, with its telephone already normalized
86	     * @return the 8-character upper-case hash segment
87	     */
88	    private String hash8(Owner owner) {
89	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
90	        return HexDigest.upperHexPrefix(telephone + owner.getLastName(), 8);
91	    }
92	}
