1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Derives the Luhn check digit for an owner identifier, computed over the digits
5	 * contained in the identifier's value (today the owner's {@code customerCode}).
6	 * Kept out of {@link OwnerMapper} so MapStruct does not mistake it for an implicit
7	 * property mapping method.
8	 */
9	public final class CheckDigitResolver {
10	
11	    private CheckDigitResolver() {
12	    }
13	
14	    /**
15	     * Returns the Luhn check digit (0-9) computed over the digits contained in the
16	     * given identifier value. Non-digit characters are ignored, so the value may be
17	     * any identifier (or identifier segment) the check digit is appended to.
18	     *
19	     * @param value the identifier value to check, may be {@code null}
20	     * @return the Luhn check digit, between 0 and 9 inclusive
21	     */
22	    public static int deriveCheckDigit(String value) {
23	        int sum = 0;
24	        boolean dbl = true;
25	        if (value != null) {
26	            for (int i = value.length() - 1; i >= 0; i--) {
27	                char c = value.charAt(i);
28	                if (c < '0' || c > '9') {
29	                    continue;
30	                }
31	                int d = c - '0';
32	                if (dbl) {
33	                    d *= 2;
34	                    if (d > 9) {
35	                        d -= 9;
36	                    }
37	                }
38	                sum += d;
39	                dbl = !dbl;
40	            }
41	        }
42	        return (10 - (sum % 10)) % 10;
43	    }
44	}
