2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's marketing 'ownerSegment', formatted {@code <TIER>_<AREA>}. TIER is
7	 * {@code PREMIUM} when the owner's {@link MembershipLevelResolver#deriveMembershipLevel(Owner)
8	 * membershipLevel} is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's
9	 * {@link LocalityResolver#deriveLocality(String) locality} is a known {@link Region} (NSW, VIC or
10	 * QLD), otherwise {@code REGIONAL}. The result is one of {@code PREMIUM_METRO},
11	 * {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}. Kept out of
12	 * {@link OwnerMapper} so MapStruct does not mistake it for an implicit property mapping method.
13	 */
14	public final class OwnerSegmentResolver {
15	
16	    /** Membership level at or above which an owner is in the {@code PREMIUM} tier. */
17	    private static final int PREMIUM_MIN_LEVEL = 3;
18	
19	    private OwnerSegmentResolver() {
20	    }
21	
22	    /**
23	     * Returns the marketing segment for an owner, formatted {@code <TIER>_<AREA>} (see
24	     * {@link OwnerSegmentResolver class docs}).
25	     *
26	     * @param owner the owner whose segment should be derived
27	     * @return the owner's segment, one of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
28	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}
29	     */
30	    public static String deriveOwnerSegment(Owner owner) {
31	        String tier = MembershipLevelResolver.deriveMembershipLevel(owner) >= PREMIUM_MIN_LEVEL
32	            ? "PREMIUM" : "STANDARD";
33	        String locality = LocalityResolver.deriveLocality(owner.getCustomerCode());
34	        String area = isKnownRegion(locality) ? "METRO" : "REGIONAL";
35	        return tier + "_" + area;
36	    }
37	
38	    /**
39	     * Reports whether the given locality names a known {@link Region} (NSW, VIC or QLD).
40	     *
41	     * @param locality the owner's locality, may be the {@link LocalityResolver#UNKNOWN} sentinel
42	     * @return {@code true} when the locality is a known region, {@code false} otherwise
43	     */
44	    private static boolean isKnownRegion(String locality) {
45	        for (Region region : Region.values()) {
46	            if (region.name().equals(locality)) {
47	                return true;
48	            }
49	        }
50	        return false;
51	    }
52	}
