1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Derives fiscal-year values from an owner's business-day-adjusted registration
8	 * date. The fiscal year runs from 1 July to 30 June and is identified by the
9	 * calendar year in which it ends (so a date on or after 1 July belongs to the
10	 * fiscal year ending the following calendar year). Kept out of {@link OwnerMapper}
11	 * so MapStruct does not mistake it for an implicit property mapping method.
12	 */
13	public final class FiscalYearResolver {
14	
15	    /** The month the fiscal year starts on (1 July). */
16	    private static final int FISCAL_YEAR_START_MONTH = Month.JULY.getValue();
17	
18	    private FiscalYearResolver() {
19	    }
20	
21	    /**
22	     * Returns the fiscal year that {@code date} falls in, identified by the
23	     * calendar year in which the fiscal year ends. Dates from 1 July onwards
24	     * belong to the fiscal year ending the following calendar year; dates up to
25	     * 30 June belong to the fiscal year ending in the same calendar year.
26	     *
27	     * @param date the date to evaluate
28	     * @return the four-digit fiscal year
29	     */
30	    public static int fiscalYear(LocalDate date) {
31	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
32	    }
33	
34	    /**
35	     * Returns the two-digit fiscal-year segment {@code <YY>}, the last two digits
36	     * of the {@link #fiscalYear(LocalDate) fiscal year}, zero-padded. This is the
37	     * shared building block of every value the fiscal year prefixes: the
38	     * {@link #deriveFiscalYear(LocalDate) FY<YY> label} renders it behind an
39	     * {@code FY} prefix.
40	     *
41	     * @param date the date to evaluate, may be {@code null}
42	     * @return the two-digit fiscal-year segment, or {@code null} when no date was supplied
43	     */
44	    public static String fiscalYearSuffix(LocalDate date) {
45	        if (date == null) {
46	            return null;
47	        }
48	        return String.format("%02d", fiscalYear(date) % 100);
49	    }
50	
51	    /**
52	     * Returns the fiscal year label {@code FY<YY>}, where {@code YY} is the
53	     * {@link #fiscalYearSuffix(LocalDate) two-digit fiscal-year segment}.
54	     *
55	     * @param date the date to evaluate, may be {@code null}
56	     * @return the fiscal-year label, or {@code null} when no date was supplied
57	     */
58	    public static String deriveFiscalYear(LocalDate date) {
59	        String suffix = fiscalYearSuffix(date);
60	        return suffix == null ? null : "FY" + suffix;
61	    }
62	
63	    /**
64	     * Returns the number of whole fiscal years elapsed between {@code from} and
65	     * {@code to}, i.e. the number of 1 July boundaries crossed. Zero (or negative)
66	     * when both dates fall in the same fiscal year (or {@code to} precedes
67	     * {@code from}).
68	     *
69	     * @param from the earlier date
70	     * @param to   the later date
71	     * @return the number of elapsed fiscal years
72	     */
73	    public static int elapsedFiscalYears(LocalDate from, LocalDate to) {
74	        return fiscalYear(to) - fiscalYear(from);
75	    }
76	}
