323	    /**
324	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
325	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
326	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
327	     * {@link #countNamesakes}), {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) and
328	     * {@code capacityWarning} (see {@link #computeCapacityWarning}) are snapshots of the existing owners taken before
329	     * this owner is saved, so none counts the new owner itself; and the shared
330	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
331	     * last name and postcode, so it is in place before the owner's household membership level is capped (see
332	     * {@link #cappedMembershipLevel}). The owner is mutated in place; the caller applies the duplicate guards and saves it.
333	     *
334	     * @param owner          the newly mapped owner about to be saved
335	     * @param ownerFieldsDto the incoming owner payload
336	     */
337	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
338	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
339	        owner.setNamesakeCount(countNamesakes(owner));
340	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
341	        owner.setCapacityWarning(computeCapacityWarning(owner.getCity()));
342	        assignHouseholdId(owner);
