345	    /**
346	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
347	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
348	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
349	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
350	     * that predate this create; distinct owners therefore always receive distinct customer codes.
351	     *
352	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
353	     * @return the de-duplicated customer code, unique across all existing owners
354	     */
355	    private String deriveUniqueCustomerCode(Owner owner) {
356	        String base = identityKeyResolver.deriveCustomerCode(owner);
357	        Collection<Owner> existing = this.clinicService.findAllOwners();
358	        String candidate = base;
359	        int n = 2;
360	        while (isCustomerCodeInUse(candidate, existing)) {
361	            candidate = base + "-" + n;
362	            n++;
363	        }
364	        return candidate;
365	    }
366	
367	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
368	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
369	    }
