371	    /**
372	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
373	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
374	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
375	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
376	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
377	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
378	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
379	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
380	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
381	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
382	     * assigned (see {@link #requireUniqueIdentity}).
383	     *
384	     * @param ownerFieldsDto the incoming owner payload, mutated in place
385	     * @throws MissingOwnerFieldsException if any required field is missing or blank
386	     */
387	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
388	        normalizeAddress(ownerFieldsDto);
389	        validateRequiredFields(ownerFieldsDto);
390	        validatePostcode(ownerFieldsDto);
391	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
392	        ownerFieldsDto.setTelephone(telephone);
393	        requireCityHasCapacity(ownerFieldsDto.getCity());
394	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
395	        ownerFieldsDto.setRegistrationDate(registrationDate);
396	        requireDailyLimitNotReached(registrationDate);
397	        normalizeEmail(ownerFieldsDto);
398	    }
