400	    /**
401	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
402	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
403	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
404	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
405	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
406	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
407	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
408	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
409	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
410	     *
411	     * @param ownerFieldsDto the incoming owner payload, mutated in place
412	     */
413	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
414	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
415	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
416	        if (!line1.isEmpty()) {
417	            ownerFieldsDto.setAddressLine1(line1);
418	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
419	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
420	        }
421	        else {
422	            ownerFieldsDto.setAddressLine1(null);
423	            ownerFieldsDto.setAddressLine2(null);
424	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
425	        }
426	    }
