428	    /**
429	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
430	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
431	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
432	     * place so the caller can map and save it directly.
433	     *
434	     * @param ownerFieldsDto the incoming owner payload, mutated in place
435	     */
436	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
437	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
438	    }
