440	    /**
441	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
442	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
443	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
444	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
445	     * date is rejected.
446	     *
447	     * @param ownerFieldsDto the incoming owner payload
448	     * @return the effective registration date rolled forward onto a business day
449	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
450	     */
451	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
452	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
453	        if (effective == null) {
454	            effective = LocalDate.now();
455	        }
456	        else if (effective.isAfter(LocalDate.now())) {
457	            throw new FutureRegistrationDateException(
458	                "the registration date must not be later than the current server date");
459	        }
460	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
461	            || PUBLIC_HOLIDAYS.contains(effective)) {
462	            effective = effective.plusDays(1);
463	        }
464	        return effective;
465	    }
