467	    /**
468	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
469	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
470	     * further owner may be created for that day.
471	     *
472	     * @param registrationDate the adjusted business-day registration date of the owner being created
473	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
474	     */
475	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
476	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
477	            throw new DailyOwnerLimitExceededException(
478	                "the maximum number of owners for today has already been reached");
479	        }
480	    }
