482	    /**
483	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
484	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
485	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
486	     * warning threshold) so both express the same per-day count in one place.
487	     *
488	     * @param registrationDate the adjusted business-day registration date to count owners for
489	     * @return the number of existing owners registered on that day
490	     */
491	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
492	        return this.clinicService.findAllOwners().stream()
493	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
494	            .count();
