511	     * Counts how many existing owners already share the given owner's first and last name, compared
512	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
513	     * create; it is zero when the owner's name is unique.
514	     *
515	     * @param owner the newly mapped owner about to be saved
516	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
517	     */
518	    private int countNamesakes(Owner owner) {
519	        String firstName = owner.getFirstName();
520	        String lastName = owner.getLastName();
521	        return (int) this.clinicService.findAllOwners().stream()
522	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
523	                && lastName.equalsIgnoreCase(existing.getLastName()))
524	            .count();
