527	    /**
528	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
529	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
530	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
531	     *
532	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
533	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
534	     * flat {@code address}.
535	     *
536	     * @param ownerFieldsDto the owner payload to validate
537	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
538	     */
539	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
540	        List<String> missingFields = new ArrayList<>();
541	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
542	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
543	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
544	        requireText(missingFields, "city", ownerFieldsDto.getCity());
545	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
546	        if (!missingFields.isEmpty()) {
547	            throw new MissingOwnerFieldsException(missingFields);
548	        }
549	    }
