557	    /**
558	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
559	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
560	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
561	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
562	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
563	     *
564	     * @param ownerFieldsDto the incoming owner payload
565	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
566	     */
567	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
568	        String postcode = ownerFieldsDto.getPostcode();
569	        if (postcode == null) {
570	            return;
571	        }
572	        Region region = Region.forCity(ownerFieldsDto.getCity());
573	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
574	            throw new InvalidPostcodeException(
575	                "postcode " + postcode + " is not valid for the city's region " + region.name());
576	        }
577	    }
