579	    /**
580	     * Rejects creating an owner whose whole derived {@code identityKey} (see
581	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
582	     * duplicate only when its normalized telephone, email and last-name Soundex all match another owner's. This single
583	     * identity key is now the sole duplicate rule: because the telephone is part of the key, owners that share only
584	     * their last name and postcode but carry different telephones have distinct keys and are not caught here — they are
585	     * created and flagged as a soft match instead (see {@link #flagPossibleDuplicate}), their membership level being
586	     * capped where they join an existing household (see {@link #cappedMembershipLevel}). Owners that have been
587	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted owner
588	     * does not block the create.
589	     *
590	     * @param owner the newly mapped owner about to be saved, with its normalized fields already in place
591	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
592	     */
593	    private void requireUniqueIdentity(Owner owner) {
594	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
595	        boolean inUse = this.clinicService.findAllOwners().stream()
596	            .filter(existing -> !existing.isDeleted())
597	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
598	        if (inUse) {
599	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
600	        }
601	    }
