603	    /**
604	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared the hard-duplicate
605	     * guard (see {@link #requireUniqueIdentity}), so it is still being created; this only records a warning. A declared
606	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
607	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
608	     * duplicate when some existing owner shares its last-name Soundex (see {@link SoundexResolver#soundex}) and its
609	     * postcode but has a different {@code identityKey}. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
610	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
611	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
612	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
613	     *
614	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
615	     * @param ownerFieldsDto the incoming owner payload
616	     */
617	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
618	        owner.setPossibleDuplicate(false);
619	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
620	            return;
621	        }
622	        String postcode = owner.getPostcode();
623	        if (postcode == null || postcode.isBlank()) {
624	            return;
625	        }
626	        for (Owner existing : this.clinicService.findAllOwners()) {
627	            if (isPossibleDuplicateOf(owner, existing)) {
628	                owner.setPossibleDuplicate(true);
629	                owner.setPossibleDuplicateOf(existing.getId());
630	                return;
631	            }
632	        }
633	    }
