635	    /**
636	     * Decides whether {@code existing} makes {@code owner} a possible (soft) duplicate: some other owner whose last-name
637	     * Soundex (see {@link SoundexResolver#soundex}) and postcode both match {@code owner}'s but whose derived
638	     * {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) differs. An equal identity key would make
639	     * the two a hard duplicate, already rejected by {@link #requireUniqueIdentity}; a differing key with a matching
640	     * name-sound and postcode — for instance two owners sharing a last name and postcode but carrying different
641	     * telephones — is the soft match this flags. The postcode-present guard is applied by the caller (see
642	     * {@link #flagPossibleDuplicate}), so {@code owner}'s postcode is non-blank here.
643	     *
644	     * @param owner    the newly mapped owner about to be saved, with its normalized fields already in place
645	     * @param existing an already-persisted owner to test the new owner against
646	     * @return {@code true} when {@code existing} makes {@code owner} a possible duplicate
647	     */
648	    private boolean isPossibleDuplicateOf(Owner owner, Owner existing) {
649	        return SoundexResolver.soundex(owner.getLastName()).equals(SoundexResolver.soundex(existing.getLastName()))
650	            && owner.getPostcode().equals(existing.getPostcode())
651	            && !identityKeyResolver.deriveIdentityKey(owner).equals(identityKeyResolver.deriveIdentityKey(existing));
652	    }
