654	    /**
655	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
656	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
657	     *
658	     * @param city the city of the owner being created
659	     * @throws OwnerCityFullException if the city already contains 50 or more owners
660	     */
661	    private void requireCityHasCapacity(String city) {
662	        if (countOwnersInCity(city) >= MAX_OWNERS_PER_CITY) {
663	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
664	        }
