715	    /**
716	     * Returns an owner's household-capped membership level: the level the {@link MembershipLevelResolver} derives from
717	     * the owner (see {@link MembershipLevelResolver#deriveMembershipLevel(Owner)}), lowered where necessary so it never
718	     * exceeds one above the highest capped level among the owner's <em>existing</em> household members — the members
719	     * that predate the owner, identified as those sharing its non-null {@code householdId} with a smaller id. When the
720	     * owner has no such existing household member (it is the first in its household, or has no household at all) no cap
721	     * applies and the derived level is returned unchanged. The owner's transient household member count is populated
722	     * first (see {@link #populateHouseholdMemberCount}) so the derived level reflects the current household size.
723	     *
724	     * @param owner the owner whose capped membership level should be computed
725	     * @return the membership level, capped at one above the existing household maximum
726	     */
727	    private int cappedMembershipLevel(Owner owner) {
728	        populateHouseholdMemberCount(owner);
729	        int level = MembershipLevelResolver.deriveMembershipLevel(owner);
730	        Integer cap = householdMembershipLevelCap(owner);
731	        return cap == null ? level : Math.min(level, cap);
732	    }
733	
734	    /**
735	     * Computes the ceiling the {@link #cappedMembershipLevel level-ceiling rule} imposes on a new owner: one above the
736	     * highest capped membership level among the owner's existing household members, or {@code null} when there is none.
737	     * An existing household member is an owner sharing this owner's non-null {@code householdId} whose id is smaller (so
738	     * it predates this owner); their levels are read with {@link #cappedMembershipLevel}, so each member's own ceiling
739	     * is respected in turn. An owner with no household ({@code null} householdId), no id yet, or no existing household
740	     * member has no cap.
741	     *
742	     * @param owner the owner whose household level cap should be computed
743	     * @return one above the existing household maximum level, or {@code null} when no cap applies
744	     */
745	    private Integer householdMembershipLevelCap(Owner owner) {
746	        String householdId = owner.getHouseholdId();
747	        Integer id = owner.getId();
748	        if (householdId == null || id == null) {
749	            return null;
750	        }
751	        Integer maxLevel = null;
752	        for (Owner member : this.clinicService.findAllOwners()) {
753	            Integer memberId = member.getId();
754	            if (memberId != null && memberId < id && householdId.equals(member.getHouseholdId())) {
755	                int memberLevel = cappedMembershipLevel(member);
756	                maxLevel = (maxLevel == null) ? memberLevel : Math.max(maxLevel, memberLevel);
757	            }
758	        }
759	        return maxLevel == null ? null : maxLevel + 1;
760	    }
761	
762	    /**
763	     * Returns the owners that belong to the given owner's household: those sharing the same non-null
764	     * {@code householdId}. An owner with no household ({@code null} householdId) is a household of one and is returned on
765	     * its own. The lookup runs against {@link ClinicService#findAllOwners()} and, like the household member count it
766	     * backs (see {@link #populateHouseholdMemberCount}), does not exclude soft-deleted owners. When the owner has
767	     * already been saved it is itself among the members returned.
768	     *
769	     * @param owner the owner whose household members should be resolved
770	     * @return the members of the owner's household, never empty
771	     */
772	    private List<Owner> householdMembers(Owner owner) {
773	        String householdId = owner.getHouseholdId();
774	        if (householdId == null) {
775	            return List.of(owner);
776	        }
777	        return this.clinicService.findAllOwners().stream()
778	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
779	            .toList();
780	    }
781	
782	    /**
783	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
784	     * household (see {@link #householdMembers}), i.e. those sharing the same non-null {@code householdId} (including the
785	     * owner itself). An owner with no household is counted as a household of one.
786	     *
787	     * @param owner the owner whose household size should be resolved
788	     */
789	    private void populateHouseholdMemberCount(Owner owner) {
790	        owner.setHouseholdMemberCount(householdMembers(owner).size());
791	    }
792	
793	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
794	    @Override
795	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
796	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
797	        if (currentOwner == null) {
798	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
799	        }
800	        validatePostcode(ownerFieldsDto);
801	        currentOwner.setAddress(ownerFieldsDto.getAddress());
802	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
803	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
804	        currentOwner.setCity(ownerFieldsDto.getCity());
805	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
806	        currentOwner.setLastName(ownerFieldsDto.getLastName());
807	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
808	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
809	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
810	        this.clinicService.saveOwner(currentOwner);
811	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
812	    }
813	
814	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
815	    @Transactional
816	    @Override
817	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
818	        Owner owner = this.clinicService.findOwnerById(ownerId);
819	        if (owner == null) {
820	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
821	        }
822	        owner.setDeleted(true);
823	        this.clinicService.saveOwner(owner);
824	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
825	    }
826	
827	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
828	    @Override
829	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
830	        Owner owner = this.clinicService.findOwnerById(ownerId);
831	        if (owner == null) {
832	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
833	        }
834	        HttpHeaders headers = new HttpHeaders();
835	        Pet pet = petMapper.toPet(petFieldsDto);
836	        owner.setId(ownerId);
837	        pet.setOwner(owner);
838	        pet.getType().setName(null);
839	        this.clinicService.savePet(pet);
840	        PetDto petDto = petMapper.toPetDto(pet);
841	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
842	            .buildAndExpand(pet.getId()).toUri());
843	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
844	    }
845	
846	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
847	    @Override
848	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
849	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
850	        if (currentOwner != null) {
851	            Pet currentPet = this.clinicService.findPetById(petId);
852	            if (currentPet != null) {
853	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
854	                currentPet.setName(petFieldsDto.getName());
855	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
856	                this.clinicService.savePet(currentPet);
857	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
858	            }
859	        }
860	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
861	    }
862	
863	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
864	    @Override
865	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
866	        HttpHeaders headers = new HttpHeaders();
867	        Visit visit = visitMapper.toVisit(visitFieldsDto);
868	        Pet pet = new Pet();
869	        pet.setId(petId);
870	        visit.setPet(pet);
871	        this.clinicService.saveVisit(visit);
872	        VisitDto visitDto = visitMapper.toVisitDto(visit);
873	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
874	            .buildAndExpand(visit.getId()).toUri());
875	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
876	    }
877	
878	
879	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
880	    @Override
881	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
882	        Owner owner = this.clinicService.findOwnerById(ownerId);
883	        if (owner != null) {
884	            Pet pet = owner.getPet(petId);
885	            if (pet != null) {
886	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
887	            }
888	        }
889	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
890	    }
891	}
