3	/**
4	 * The canonical regions an owner's city can belong to. Modeling a region as a first-class type
5	 * (rather than a bare string) gives the region-keyed rules a single home: each region owns the
6	 * cities that resolve to it, so further region-scoped facts can hang off the same constant instead
7	 * of being duplicated as a parallel city switch.
8	 *
9	 * <p>Kept in the {@code mapper} package alongside {@link LocalityResolver}, which turns a region
10	 * into the {@code locality} string an owner is mapped with. Not a {@code @Mapper} type, so MapStruct
11	 * ignores it.
12	 */
13	public enum Region {
14	
15	    NSW("Sydney", 2000, 2099, "Australia/Sydney"),
16	    VIC("Melbourne", 3000, 3099, "Australia/Melbourne"),
17	    QLD("Brisbane", 4000, 4099, "Australia/Brisbane");
18	
19	    private final String city;
20	
21	    private final int minPostcode;
22	
23	    private final int maxPostcode;
24	
25	    private final String timezone;
26	
27	    Region(String city, int minPostcode, int maxPostcode, String timezone) {
28	        this.city = city;
29	        this.minPostcode = minPostcode;
30	        this.maxPostcode = maxPostcode;
31	        this.timezone = timezone;
32	    }
33	
34	    /**
35	     * Returns this region's IANA timezone name (NSW {@code Australia/Sydney}, VIC
36	     * {@code Australia/Melbourne}, QLD {@code Australia/Brisbane}).
37	     *
38	     * @return the region's IANA timezone name
39	     */
40	    public String getTimezone() {
41	        return this.timezone;
42	    }
43	
44	    /**
45	     * Returns whether the given (already 4-digit) postcode falls within this region's inclusive
46	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
47	     *
48	     * @param postcode the numeric postcode value to test
49	     * @return {@code true} when the postcode is within the region's range, {@code false} otherwise
50	     */
51	    public boolean acceptsPostcode(int postcode) {
52	        return postcode >= this.minPostcode && postcode <= this.maxPostcode;
53	    }
54	
55	    /**
56	     * Returns the region whose inclusive postcode range contains the given postcode, or
57	     * {@code null} when the postcode is absent, not a 4-digit number, or in no known range.
58	     *
59	     * @param postcode the owner's postcode, may be {@code null}
60	     * @return the matching region, or {@code null} when the postcode maps to no known region
61	     */
62	    public static Region forPostcode(String postcode) {
63	        if (postcode == null) {
64	            return null;
65	        }
66	        int value;
67	        try {
68	            value = Integer.parseInt(postcode.trim());
69	        }
70	        catch (NumberFormatException ex) {
71	            return null;
72	        }
73	        for (Region region : values()) {
74	            if (region.acceptsPostcode(value)) {
75	                return region;
76	            }
77	        }
78	        return null;
