86	     * @return the matching region, or {@code null} when the city belongs to no known region
87	     */
88	    public static Region forCity(String city) {
89	        if (city == null) {
90	            return null;
91	        }
92	        for (Region region : values()) {
93	            if (region.city.equals(city)) {
94	                return region;
95	            }
96	        }
97	        return null;
98	    }
99	}
