3	/**
4	 * Derives the American Soundex code of a name. Soundex reduces a surname to a phonetic key — a retained first letter
5	 * followed by three digits encoding its remaining consonant sounds — so names that sound alike share a code. It is used
6	 * both in the owner {@code identityKey} (see {@link IdentityKeyResolver#deriveIdentityKey}) and in the soft-duplicate
7	 * match, which fires when two owners share a last-name Soundex and a postcode but differ in identity key. Kept a static
8	 * utility like {@link HexDigest} and {@link LocalityResolver}, since it derives purely from its argument.
9	 */
10	public final class SoundexResolver {
11	
12	    private SoundexResolver() {
13	    }
14	
15	    /**
16	     * Returns the four-character American Soundex code of {@code name}: its first letter followed by three digits, or
17	     * an empty string when the name carries no letters. Non-letter characters are ignored; the coding is
18	     * case-insensitive. Consecutive letters mapping to the same digit collapse to one, letters separated only by
19	     * {@code 'h'} or {@code 'w'} are treated as adjacent, and the code is right-padded with zeros and truncated to
20	     * four characters.
21	     *
22	     * @param name the name to encode, may be {@code null}
23	     * @return the four-character Soundex code, or an empty string when {@code name} has no letters
24	     */
25	    public static String soundex(String name) {
26	        if (name == null) {
27	            return "";
28	        }
29	        StringBuilder letters = new StringBuilder();
30	        for (int i = 0; i < name.length(); i++) {
31	            char c = name.charAt(i);
32	            if (Character.isLetter(c)) {
33	                letters.append(Character.toUpperCase(c));
34	            }
35	        }
36	        if (letters.length() == 0) {
37	            return "";
38	        }
39	        StringBuilder code = new StringBuilder();
40	        code.append(letters.charAt(0));
41	        char previousCode = codeOf(letters.charAt(0));
42	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
43	            char c = letters.charAt(i);
44	            char digit = codeOf(c);
45	            if (digit != '0' && digit != previousCode) {
46	                code.append(digit);
47	            }
48	            if (c != 'H' && c != 'W') {
49	                previousCode = digit;
50	            }
51	        }
52	        while (code.length() < 4) {
53	            code.append('0');
54	        }
55	        return code.toString();
56	    }
57	
58	    /**
59	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for the letters that carry no digit
60	     * ({@code a, e, i, o, u, y, h, w}).
61	     */
62	    private static char codeOf(char c) {
63	        switch (c) {
64	            case 'B': case 'F': case 'P': case 'V':
65	                return '1';
66	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
67	                return '2';
68	            case 'D': case 'T':
69	                return '3';
70	            case 'L':
71	                return '4';
72	            case 'M': case 'N':
73	                return '5';
74	            case 'R':
75	                return '6';
76	            default:
77	                return '0';
78	        }
79	    }
80	}
